S=dict(cls=6,subj="social-science",subj_file="social-science")
build(dict(S,ch="locating-places-on-the-earth",topic="latitudes-and-longitudes",name_en="Latitudes and longitudes",name_ta="அட்சக்கோடுகள், தீர்க்கக்கோடுகள்",
 objectives=["Say what latitudes and longitudes are","Name the Equator, Prime Meridian and the hemispheres"],
 story=("The treasure map","Zoya drew a treasure map for her friends. \"The treasure is in the park,\" she wrote. Nobody could find it.\nHer brother added two numbers: how far across, and how far up. Now everyone found it in a minute.\n\"Maps need exact addresses,\" he said. \"On the Earth, those addresses are latitudes and longitudes.\""),
 explain=["A globe is a model of the Earth. Imaginary lines drawn on it help us find any place exactly.","Lines of latitude run east to west and are parallel circles. The Equator is at 0° latitude. It divides the Earth into the Northern Hemisphere and the Southern Hemisphere.","Important latitudes are the Tropic of Cancer (23½° N), the Tropic of Capricorn (23½° S), the Arctic Circle (66½° N) and the Antarctic Circle (66½° S).","Lines of longitude run from the North Pole to the South Pole. The Prime Meridian is at 0° and passes through Greenwich, London. It and the 180° line divide the Earth into the Eastern Hemisphere and the Western Hemisphere.","A place is found where its latitude and longitude cross. India lies in the Northern and Eastern hemispheres, and the Tropic of Cancer passes through it."],
 terms=["globe","latitude","longitude","Equator","Prime Meridian","hemisphere"],
 narr=[("Latitudes run east to west. The Equator is zero degrees and splits the Earth into northern and southern halves.","Equator 0°"),("Longitudes run from pole to pole. The Prime Meridian is zero degrees and passes through Greenwich.","Prime Meridian 0°"),("The Tropic of Cancer is twenty-three and a half degrees north. It passes through India.","Tropic of Cancer 23½° N"),("A place is found where its latitude and longitude cross, like an exact address.","latitude + longitude = address")],
 ex=("India is north of the Equator and east of the Prime Meridian. In which hemispheres does India lie?",[("North of the Equator means the Northern Hemisphere.","The Equator separates north and south."),("East of the Prime Meridian means the Eastern Hemisphere.","The Prime Meridian separates east and west."),("So India lies in the Northern and Eastern hemispheres.","Both facts together give the answer.")]),
 tb=("Your friend asks why we need latitudes and longitudes when we have place names. What will you say?",["Many places have the same name, but latitude and longitude give an exact position.","Ships and planes use them to find their way."],["Thinking the lines are real lines on the ground."]),
 summary=["Latitudes run east-west; the Equator is 0°.","Longitudes run pole to pole; the Prime Meridian is 0°.","Latitude and longitude together fix a place exactly."],
 q=[("mcq",1,"r1-equator","What is the latitude of the Equator?","0 degrees",[("90 degrees","The poles are at 90 degrees."),("23½ degrees","That is the Tropic of Cancer or Capricorn.")],"The Equator is at 0° latitude."),
    ("tf",1,"r1-lines","Latitudes and longitudes are imaginary lines.",True,"True. They are drawn on maps and globes to help us."),
    ("mcq",2,"r2-prime","The Prime Meridian passes through","Greenwich in London",[("Delhi","It does not pass through Delhi."),("Chennai","It does not pass through Chennai.")],"The Prime Meridian is at 0° and passes through Greenwich."),
    ("tf",2,"r2-run","Lines of latitude run from the North Pole to the South Pole.",False,"False. Lines of longitude do that; latitudes run east to west."),
    ("mcq",3,"r3-hemi","The Equator divides the Earth into","Northern and Southern hemispheres",[("Eastern and Western hemispheres","The Prime Meridian and 180° line do that."),("two equal oceans","It does not divide oceans in that way.")],"The Equator gives the Northern and Southern hemispheres."),
    ("short",3,"r3-cancer","Which tropic passes through India?",["tropic of cancer","cancer"],"The Tropic of Cancer passes through India."),
    ("mcq",4,"r4-india","In which hemispheres does India lie?","Northern and Eastern",[("Southern and Western","India is north of the Equator and east of the Prime Meridian."),("Southern and Eastern","India is north of the Equator.")],"India is north of the Equator and east of the Prime Meridian."),
    ("tf",4,"r4-cross","A place can be found where its latitude and longitude cross.",True,"True.")]))
build(dict(S,ch="oceans-and-continents",topic="oceans-and-continents-of-the-earth",name_en="Oceans and continents of the Earth",name_ta="பூமியின் பெருங்கடல்களும் கண்டங்களும்",
 objectives=["Name the five oceans and seven continents","Say which is the largest and the smallest"],
 story=("Blue planet","From a spaceship window, an astronaut saw the Earth as a blue ball with brown and green patches.\n\"The blue is water and the patches are land,\" she told the children on a video call. \"Most of our planet is covered by oceans.\""),
 explain=["About 71 percent of the Earth is covered with water and about 29 percent is land. That is why the Earth is called the blue planet.","The large pieces of land are continents. There are seven: Asia, Africa, North America, South America, Antarctica, Europe and Australia. Asia is the largest and Australia is the smallest.","The big water bodies are oceans. There are five: the Pacific, Atlantic, Indian, Southern and Arctic oceans. The Pacific Ocean is the largest and the Arctic Ocean is the smallest.","India is in the continent of Asia. The Indian Ocean lies to its south, with the Bay of Bengal on the east and the Arabian Sea on the west.","Oceans give us food, salt, minerals and rain, and ships carry goods across them."],
 terms=["continent","ocean","Pacific Ocean","Asia"],
 narr=[("About seventy-one percent of the Earth is water, so it is called the blue planet.","71% water, 29% land"),("There are seven continents. Asia is the largest and Australia the smallest.","7 continents"),("There are five oceans. The Pacific is the largest and the Arctic is the smallest.","5 oceans"),("India is in Asia. The Indian Ocean is to its south.","India: Asia, Indian Ocean")],
 ex=("Count the continents and oceans, and name the largest of each.",[("There are 7 continents and 5 oceans.","These are the standard numbers."),("Asia is the largest continent.","It has the biggest area of land."),("The Pacific Ocean is the largest ocean.","It is bigger than all other oceans.")]),
 tb=("A friend thinks land covers more of the Earth than water. How will you correct him?",["About 71 percent of the Earth is water and 29 percent is land.","So water covers more of the Earth."],["Thinking land is the bigger part."]),
 summary=["Water covers about 71 percent of the Earth.","Seven continents and five oceans.","Asia and the Pacific Ocean are the largest."],
 q=[("mcq",1,"r1-largest","Which is the largest continent?","Asia",[("Africa","Africa is the second largest."),("Europe","Europe is much smaller.")],"Asia is the largest continent."),
    ("tf",1,"r1-seven","There are seven continents.",True,"True."),
    ("mcq",2,"r2-ocean","Which is the largest ocean?","Pacific Ocean",[("Indian Ocean","The Pacific is larger."),("Arctic Ocean","The Arctic is the smallest.")],"The Pacific Ocean is the largest."),
    ("tf",2,"r2-land","Land covers more of the Earth than water.",False,"False. Water covers about 71 percent."),
    ("mcq",3,"r3-five","How many oceans are there?","five",[("three","There are five."),("seven","There are seven continents.")],"There are five oceans."),
    ("short",3,"r3-india","India is in which continent?",["asia"],"India is in Asia."),
    ("mcq",4,"r4-small","Which is the smallest continent?","Australia",[("Europe","Europe is larger than Australia."),("Antarctica","Antarctica is larger than Australia.")],"Australia is the smallest continent."),
    ("tf",4,"r4-south","The Indian Ocean lies to the south of India.",True,"True.")]))
build(dict(S,ch="landforms-and-life",topic="mountains-plateaus-and-plains",name_en="Mountains, plateaus and plains",name_ta="மலைகள், பீடபூமிகள், சமவெளிகள்",
 objectives=["Describe mountains, plateaus and plains","Say how landforms affect the way people live"],
 story=("Three homes","Three children lived in three places. Tenzin lived on a mountain, Ravi on a plateau and Lata on a river plain.\nTenzin's family kept yaks and wore thick wool. Ravi's family dug minerals from the rocks. Lata's family grew rice in wide green fields.\n\"The land shapes how we live,\" said Lata."),
 explain=["The shapes of the Earth's surface are called landforms. The three main ones are mountains, plateaus and plains.","Mountains are very high and rise steeply. They are cold at the top and have thin air. The Himalayas are the highest mountains in the world.","A plateau is a high flat-topped land with steep sides. It is rich in minerals. The Deccan Plateau is in southern India.","Plains are large flat lands, often near rivers, with fertile soil. Crops grow well and many people live there. The Ganga plain is one of the most populated.","Life depends on landforms. Mountains have fewer people, forests and tourism. Plateaus have mining. Plains have farming, towns and roads."],
 terms=["landform","mountain","plateau","plain","fertile"],
 narr=[("The shapes on the Earth's surface are landforms: mountains, plateaus and plains.","mountain, plateau, plain"),("Mountains are high and steep. The Himalayas are the highest in the world.","mountains: Himalayas"),("A plateau is a high flat land, rich in minerals. The Deccan is a plateau.","plateau: Deccan"),("Plains are flat and fertile, so crops grow well and many people live there.","plains: farming, cities")],
 ex=("Why do more people live on plains than on mountains?",[("Plains are flat with fertile soil, and rivers bring water.","Farming is easy."),("It is easy to build houses and roads there.","Mountains are steep and cold."),("So plains support more people.","Easy life draws more people.")]),
 tb=("A friend asks why the Deccan region has many mines. What will you say?",["A plateau is rich in minerals.","The rocks of the Deccan Plateau hold many minerals that people dig out."],["Thinking mines are only on mountains."]),
 summary=["Landforms: mountains, plateaus and plains.","Plains are fertile and crowded; plateaus are rich in minerals.","Landforms shape how people live."],
 q=[("mcq",1,"r1-himalaya","Which are the highest mountains in the world?","the Himalayas",[("the Deccan","The Deccan is a plateau."),("the Ganga","The Ganga is a river.")],"The Himalayas are the highest."),
    ("tf",1,"r1-plain","Plains are flat lands.",True,"True."),
    ("mcq",2,"r2-plateau","A high flat-topped land with steep sides is a","plateau",[("plain","A plain is low and flat."),("valley","A valley is low land between hills.")],"This describes a plateau."),
    ("tf",2,"r2-fertile","Mountains have the most fertile land.",False,"False. Plains have the most fertile land."),
    ("mcq",3,"r3-deccan","The Deccan is a","plateau",[("mountain","It is not a high peak."),("ocean","It is land.")],"The Deccan Plateau is in southern India."),
    ("short",3,"r3-crop","Name one thing people grow on plains.",["rice","wheat","sugarcane","crops","vegetables","pulses"],"Plains are good for crops like rice and wheat."),
    ("mcq",4,"r4-life","Why are many cities on plains?","flat land and fertile soil make life easy",[("mountains are too warm","Mountains are usually cold."),("plains have no water","Plains often have rivers.")],"Plains are easy to build on and farm."),
    ("tf",4,"r4-mine","Plateaus are rich in minerals.",True,"True.")]))
build(dict(S,ch="timeline-and-sources-of-history",topic="how-we-know-about-the-past",name_en="How we know about the past",name_ta="கடந்த காலத்தை நாம் அறியும் விதம்",
 objectives=["Name the sources of history","Read BCE and CE years on a timeline"],
 story=("The old coin","Hari found an old coin in his grandmother's trunk. It had strange letters and a king's head on it.\nHis teacher said, \"Coins, tools, buildings and old writings are clues. Historians study them to learn about the past, like detectives.\""),
 explain=["History is the story of the past. We learn it from sources, which are clues left by people long ago.","Archaeological sources are things found under or on the ground: tools, pots, coins, jewellery, ruins of buildings and inscriptions carved on stone or metal.","Literary sources are things written: books, letters, manuscripts, records. Oral sources are stories, songs and sayings passed by word of mouth.","A timeline puts events in order of time. Years before the year 1 are marked BCE (Before Common Era) and are counted backwards; years after are CE (Common Era).","Historians compare many sources to find out what really happened, because one source may be wrong or one-sided."],
 terms=["history","archaeology","inscription","manuscript","timeline","BCE","CE"],
 narr=[("History is the story of the past. We learn it from clues called sources.","sources of history"),("Tools, coins, pots and ruins are archaeological sources. Writings on stone are inscriptions.","archaeological sources"),("Books and manuscripts are written sources. Songs and stories passed by mouth are oral sources.","written and oral sources"),("A timeline lists events in order. BCE years count backwards from year one, and CE years count forwards.","BCE  |  CE")],
 ex=("Which comes earlier on a timeline: 500 BCE or 200 CE?",[("BCE years come before the year 1.","They are in the past before the common era."),("200 CE is after the year 1.","It is in the common era."),("So 500 BCE comes earlier.","BCE is earlier than CE.")]),
 tb=("A friend says history is only what is written in books. How will you reply?",["Tools, coins, buildings and inscriptions also tell us about the past.","Songs and stories passed by word of mouth are sources too."],["Thinking only books are sources."]),
 summary=["Sources: archaeological, written and oral.","BCE years are counted backwards; CE years forwards.","Historians compare many sources."],
 q=[("mcq",1,"r1-coin","An old coin is a source of","history",[("music","A coin tells us about the past."),("weather","A coin tells us about the past.")],"Coins are archaeological sources."),
    ("tf",1,"r1-oral","Stories passed by word of mouth can be sources of history.",True,"True. They are oral sources."),
    ("mcq",2,"r2-inscr","Writing carved on stone or metal is called","an inscription",[("a manuscript","A manuscript is handwritten on paper or leaves."),("a timeline","A timeline lists events in order.")],"An inscription is carved writing."),
    ("tf",2,"r2-bce","BCE years are counted forwards from year one.",False,"False. BCE years count backwards."),
    ("mcq",3,"r3-earlier","Which is earlier?","300 BCE",[("100 CE","CE is later than BCE."),("1000 CE","CE is later than BCE.")],"BCE comes before CE."),
    ("short",3,"r3-source","Name one archaeological source.",["coin","coins","tools","pots","inscription","ruins","jewellery","pottery"],"Tools, coins, pots and ruins are archaeological sources."),
    ("mcq",4,"r4-compare","Why do historians compare many sources?","one source may be wrong or one-sided",[("to waste time","That is not the reason."),("because sources are all the same","Sources differ.")],"Comparing gives a fairer picture."),
    ("tf",4,"r4-timeline","A timeline puts events in order of time.",True,"True.")]))
